package staticpod

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"text/template"
)

// ManifestFileName is the name a VM's rendered manifest is written under,
// within its StaticPodPath.
func ManifestFileName(name string) string {
	return "kontur-vm-" + name + ".yaml"
}

// PodName is the Kubernetes pod name a VM's manifest declares.
func PodName(name string) string {
	return "kontur-vm-" + name
}

// Render produces the static pod manifest YAML for spec: one pod with a
// netshim init container (wiring up this VM's tap device, bridge and NAT
// rule) and a single VM container, both running the same kontur image in
// its two modes ("netshim" and "run"). It follows the same shape as
// deploy/static-kubelet/manifests/kontur-static-pod.yaml, generated instead
// of hand-written so it can be regenerated on every "konturctl vm update".
func Render(s VMSpec) (string, error) {
	var buf bytes.Buffer
	if err := manifestTemplate.Execute(&buf, s); err != nil {
		return "", fmt.Errorf("rendering manifest for %q: %w", s.Name, err)
	}
	return buf.String(), nil
}

var manifestTemplate = template.Must(template.New("manifest").Funcs(template.FuncMap{
	"yq":      yamlQuote,
	"itoa":    strconv.Itoa,
	"PodName": PodName,
	"fmtBool": strconv.FormatBool,
}).Parse(manifestTemplateSrc))

// yamlQuote renders s as a double-quoted YAML scalar, escaping backslashes
// and double quotes so arbitrary values (paths, cmdlines, image refs) are
// always safe to interpolate regardless of what characters they contain.
func yamlQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '\\', '"':
			b.WriteByte('\\')
			b.WriteRune(r)
		case '\n':
			b.WriteString(`\n`)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

const manifestTemplateSrc = `# Generated by "konturctl vm" -- do not edit by hand, "konturctl vm update"
# will overwrite this file and "konturctl vm delete" removes it. Managed VM: {{.Name}}
apiVersion: v1
kind: Pod
metadata:
  name: {{yq (PodName .Name)}}
  labels:
    app: kontur-vm
    kontur.dev/vm: {{yq .Name}}
spec:
  restartPolicy: Always
  terminationGracePeriodSeconds: {{itoa .TerminationGracePeriodSeconds}}
  initContainers:
    - name: netshim
      image: {{yq .KonturImage}}
      args: ["netshim"]
      env:
        - name: NETSHIM_VMS
          value: {{yq (printf "%s:%s:%d" .Name .IP .Port)}}
        - name: NETSHIM_BRIDGE
          value: {{yq .Bridge}}
        - name: NETSHIM_BRIDGE_CIDR
          value: {{yq .BridgeCIDR}}
        - name: NETSHIM_EXTERNAL_IFACE
          value: {{yq .ExternalIface}}
        - name: NETSHIM_GUEST_PORT
          value: {{yq (itoa .GuestPort)}}
      securityContext:
        capabilities:
          add: ["NET_ADMIN", "NET_RAW"]
  containers:
    - name: {{yq .Name}}
      image: {{yq .KonturImage}}
      args: ["run"]
      env:
        - name: CHV_DISK_IMAGE
          value: {{yq .DiskImage}}
        - name: CHV_DISK_READONLY
          value: {{yq (fmtBool .DiskReadOnly)}}
{{- if .Kernel}}
        - name: CHV_KERNEL
          value: {{yq .Kernel}}
{{- end}}
{{- if .Initramfs}}
        - name: CHV_INITRAMFS
          value: {{yq .Initramfs}}
{{- end}}
{{- if .Firmware}}
        - name: CHV_FIRMWARE
          value: {{yq .Firmware}}
{{- end}}
{{- if .Cmdline}}
        - name: CHV_CMDLINE
          value: {{yq .Cmdline}}
{{- end}}
        - name: CHV_NET
          value: {{yq (printf "tap=tap-%s" .Name)}}
        - name: CHV_CPUS
          value: {{yq (itoa .CPUs)}}
        - name: CHV_MEMORY_MB
          value: {{yq (itoa .MemoryMB)}}
        - name: CHV_SHUTDOWN_TIMEOUT
          value: {{yq .ShutdownTimeout}}
      securityContext:
        privileged: true
      volumeMounts:
        - name: images
          mountPath: /images
          readOnly: true
        - name: kvm
          mountPath: /dev/kvm
  volumes:
    - name: images
      hostPath:
        path: {{yq .ImagesHostPath}}
        type: Directory
    - name: kvm
      hostPath:
        path: /dev/kvm
        type: CharDevice
`
